// path: ordered list of edge ids; trafficOverlay: edgeId -> live travel seconds
function computeEta(path, trafficOverlay, staticTimes) {
  let total = 0;
  for (const edgeId of path) {
    const live = trafficOverlay[edgeId];
    total += live;            // use the live, traffic-adjusted time
  }
  return total;
}
